const solo = (s) => String(s || '').trim().toUpperCase();
const digitos = (s) => String(s || '').replace(/\D/g, '');
let porDigitos = null;
/** Motor del equipo: { marca, modelo, confianza, familia, nota, origen } o null. */
export const motorDeEquipo = (eq) => {
  if (!eq) return null;
  const k = solo(eq.afi);
  let r = MOTOR_POR_AFI[k], origen = 'afi';
  if (!r) {   // el AFI puede venir sin prefijo (ej. "402" vs "GEN 402"): por número, solo si no se repite
    if (!porDigitos) { porDigitos = {}; Object.keys(MOTOR_POR_AFI).forEach(a => { const n = digitos(a); if (n) porDigitos[n] = porDigitos[n] === undefined ? a : null; }); }
    const a = porDigitos[digitos(k)];
    if (a && digitos(k)) r = MOTOR_POR_AFI[a];
  }
  if (!r) {   // otro equipo de la misma marca y modelo
    const m = Object.values(MOTOR_POR_AFI).find(x => solo(x[5]) === solo(eq.marca) && solo(x[6]) === solo(eq.modelo) && x[3] !== 'otro');
    if (m) { r = m; origen = 'modelo'; }
  }
  if (!r) return null;
  return { marca: r[0], modelo: r[1], confianza: { A: 'Alta', M: 'Media', B: 'Baja' }[r[2]] || r[2], familia: r[3], nota: r[4], origen };
};
/** AFIs que comparten el mismo motor (para planificar compras por fabricante). */
export const equiposConMismoMotor = (marca, modelo) => Object.entries(MOTOR_POR_AFI).filter(([, x]) => x[0] === marca && x[1] === modelo).map(([a]) => a);
/** Próxima vez que toca una tarea por horas según el horómetro actual. */
export const proximaPorHoras = (horometro, intervalo) => {
  const h = Number(horometro) || 0;
  if (!(intervalo > 0) || !(h > 0)) return null;
  const prox = Math.ceil((h + 0.0001) / intervalo) * intervalo;
  return { prox, faltan: Math.round(prox - h) };
};
